"use client";
import { useEffect, useRef, useState, useTransition } from "react";
import { Check } from "lucide-react";
import { useRouter } from "next/navigation";
import { chooseFreeTemplate } from "@/lib/actions";
import type { ActionResult } from "@/lib/errors";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { Feedback } from "@/components/forms";
export function TemplateControls({
  id,
  selected,
  planLabel = "Paid",
  selectedVariant = "default",
}: {
  id: string;
  selected: boolean;
  planLabel?: "Paid" | "Premium";
  selectedVariant?: "default" | "library";
}) {
  const [pending, start] = useTransition();
  const [result, setResult] = useState<ActionResult>();
  const router = useRouter();
  const previousId = useRef(id);
  useEffect(() => {
    if (selected && previousId.current !== id)
      document.getElementById("active-free-template-title")?.focus();
    previousId.current = id;
  }, [id, selected]);
  if (selected)
    return (
      <span
        className={cn(
          "free-template-selected inline-flex items-center gap-1.5 py-1 text-[12px]",
          selectedVariant === "library"
            ? "px-3 rounded-full [background:color-mix(in_srgb,var(--success)_14%,transparent)] text-[var(--status-success-text)] font-bold"
            : "px-[9px] rounded-[6px] bg-accent-soft text-link font-medium",
        )}
      >
        <Check className="size-3.5" aria-hidden="true" />
        Active for Compose
      </span>
    );
  return (
    <div>
      <Button
        variant="outline"
        disabled={pending}
        onClick={() =>
          start(async () => {
            const response = await chooseFreeTemplate(id);
            setResult(response);
            if (response.ok) {
              router.refresh();
            }
          })
        }
      >
        {pending ? "Selecting…" : "Use as Free template"}
      </Button>
      {result?.ok === false && (
        <Feedback planLabel={planLabel} result={result} />
      )}
    </div>
  );
}
